#!/bin/bash
set -euo pipefail

# Match the source pinned in the distro recipes to the exact hosted Edge publication.
if [[ $# != 3 || ! $1 =~ ^[0-9a-f]{40}$ || ! $2 =~ ^[1-9][0-9]*$ || ! $3 =~ ^[1-9][0-9]*$ ]]; then
    echo "Usage: $0 LINUX_COMMIT PUBLISH_RUN_ID PUBLISH_ATTEMPT" >&2
    exit 2
fi
revision=$1 run_id=$2 attempt=$3
repo=aurora-silicon/linux
workflow=.github/workflows/kernel-release.yml
run="repos/$repo/actions/runs/$run_id/attempts/$attempt"
invocation="https://github.com/$repo/actions/runs/$run_id/attempts/$attempt"

gh api "$run" | jq -e --arg repo "$repo" --arg workflow "$workflow" --arg revision "$revision" \
    --arg run_id "$run_id" --arg attempt "$attempt" '
    (.id | tostring) == $run_id and (.run_attempt | tostring) == $attempt and
    .head_repository.full_name == $repo and .path == $workflow and
    .head_sha == $revision and .head_branch == "main" and
    (.event == "push" or .event == "workflow_dispatch") and
    .status == "completed" and .conclusion == "success"
' >/dev/null

gh api "$run/jobs?per_page=100" | jq -e '
    [.jobs[] | select(.name == "publish" and .conclusion == "success")]
    | length == 1 and
        (.[0].steps | map(select(.conclusion == "success").name) as $steps
        | ["Attest build provenance", "Move the channel tag", "Publish rolling prerelease"] - $steps == [])
' >/dev/null

# This is the same source.commit generated by kernel-release.yml. Asking the
# verifier for its digest avoids downloading the kernel on both signer jobs.
scratch=$(mktemp -d "${RUNNER_TEMP:-$PWD}/linux-edge.XXXXXXXX")
marker="$scratch/source.commit"
trap 'rm -f -- "$marker"; rmdir -- "$scratch"' EXIT
printf '%s\n' "$revision" > "$marker"
digest=$(sha256sum "$marker")
digest=${digest%% *}
gh attestation verify "$marker" --repo "$repo" --signer-workflow "$repo/$workflow" \
    --source-ref refs/heads/main --source-digest "$revision" --deny-self-hosted-runners --format json |
    jq -e --arg invocation "$invocation" --arg digest "$digest" '
        def required($release):
            ["source.commit", "kernel.release", "SHA256SUMS", "Image-\($release).gz",
             "modules-\($release).tar.zst", "dtbs-\($release).tar.zst", "config-\($release)",
             "System.map-\($release)", "module-signing-cert-\($release).der"];
        any(.[].verificationResult.statement;
            .predicate.runDetails.metadata.invocationId == $invocation and
            (.subject | all(.digest.sha256 | test("^[0-9a-f]{64}$"))) and
            (.subject | map(.name) | length == (unique | length)) and
            any(.subject[]; .name == "source.commit" and .digest.sha256 == $digest) and
            (.subject | map(.name) | . as $names
                | any(.[] | capture("^Image-(?<release>[0-9][0-9a-z.+_-]*-aurora-edge)\\.gz$").release;
                    . as $release | required($release) - $names == [])))
    ' >/dev/null
gh api "repos/$repo/compare/$revision...main" --jq .status | grep -Eqx 'ahead|identical'
printf '%s\n' "$digest"
